INSERT INTO atividades (slug, titulo, descricao, disciplina, disciplina_label, conceito, tempo_minutos, idade, espaco, objetivo, passos_html, dica, materiais_html, conceito_descricao) VALUES
                                                                                                                                                                                            ('amarelinha', 'Amarelinha dos Padrões', 'A amarelinha ganha uma regra de algoritmo: números pares passam, ímpares são "bug".', 'm', 'Matemática', 'Sequência e depuração', 25, '6 a 8 anos', 'Pátio ou sala',
                                                                                                                                                                                             'Introduzir números pares e ímpares e o sequenciamento. As crianças seguem uma regra, encontram o erro e tentam de novo, como em um programa.',
                                                                                                                                                                                             '<ol class="passos"><li><h3>Desenhe a amarelinha</h3><p>Faça uma amarelinha tradicional no chão e numere as casas em sequência.</p></li><li><h3>Defina a regra</h3><p>Anuncie o algoritmo: só é permitido pisar em casas com números pares.</p></li><li><h3>Pule seguindo a regra</h3><p>Cada criança percorre a amarelinha. Pisar em número ímpar acusa um "bug".</p></li><li><h3>Depure a jogada</h3><p>Quem errou volta ao início. Pergunte qual parte da regra não foi seguida e deixe tentar de novo.</p></li><li><h3>Troque de papel</h3><p>Cada criança inventa uma regra de padrão para os colegas, como pisar de três em três.</p></li></ol>',
                                                                                                                                                                                             'Chame o erro de "bug" com leveza. O objetivo é tentar de novo, não ser eliminado.',
                                                                                                                                                                                             '<ul><li><strong>Giz</strong><span>Para desenhar a amarelinha numerada.</span></li><li><strong>Pátio ou calçada</strong><span>Um espaço livre para pular.</span></li><li><strong>Cartões de padrão</strong><span>Opcional, para a rodada final.</span></li></ul>',
                                                                                                                                                                                             'Sequenciamento é organizar instruções em uma ordem para alcançar um objetivo. Depurar é achar e corrigir o erro.'),

                                                                                                                                                                                            ('chapeuzinho', 'O Algoritmo da Chapeuzinho Vermelho', 'Uma história conhecida para treinar sequência de eventos e decisões do tipo "se isso, então aquilo".', 'p', 'Língua Portuguesa', 'Se / Senão', 30, '6 a 8 anos', 'Pátio ou sala',
                                                                                                                                                                                             'Trabalhar sequência narrativa (começo, meio e fim) e condições lógicas Se/Senão. As crianças percebem que um algoritmo pode seguir caminhos diferentes conforme a situação.',
                                                                                                                                                                                             '<ol class="passos"><li><h3>Conte a história</h3><p>Destaque os acontecimentos principais, do começo ao fim.</p></li><li><h3>Espalhe os cartões</h3><p>Coloque os cartões da história no chão, fora de ordem.</p></li><li><h3>Percorra a sequência</h3><p>Um aluno por vez pisa nos cartões na ordem correta dos eventos.</p></li><li><h3>Insira a regra</h3><p>Diga: "SE você pisar no cartão do Lobo, ENTÃO recua duas casas e busca o cartão do Caçador para prosseguir".</p></li><li><h3>Convide a turma a criar</h3><p>Pergunte: e se aparecesse outro personagem? Que regra Se/Senão criamos para ele?</p></li></ol>',
                                                                                                                                                                                             'Deixe as crianças inventarem as regras. Elas lembram melhor das que elas mesmas criam.',
                                                                                                                                                                                             '<ul><li><strong>Cartões da história</strong><span>Uma cena por cartão, incluindo Lobo e Caçador.</span></li><li><strong>Espaço no chão</strong><span>Para espalhar os cartões e caminhar entre eles.</span></li><li><strong>Giz ou fita crepe</strong><span>Para marcar a trilha, se quiser.</span></li></ul>',
                                                                                                                                                                                             'Se / Senão é uma decisão: se uma condição for verdadeira, o algoritmo faz uma ação; senão, faz outra.'),

                                                                                                                                                                                            ('escravos-de-jo', 'Escravos de Jó Algorítmico', 'A cantiga tradicional vira um programa: um comando que se repete e uma condição que o altera.', 'f', 'Folclore', 'Repetição (loop)', 20, '6 a 8 anos', 'Pátio ou sala',
                                                                                                                                                                                             'Trabalhar ritmo, tradição cultural e o conceito computacional de repetição. As crianças percebem que um mesmo comando pode ser executado várias vezes e que uma condição pode mudar esse laço.',
                                                                                                                                                                                             '<ol class="passos"><li><h3>Monte a roda</h3><p>Sente a turma em círculo e entregue um objeto a cada criança, na frente dela.</p></li><li><h3>Ensine o comando base</h3><p>Ao cantar, todos passam o objeto para a direita no ritmo da música. Esse é o comando que se repete.</p></li><li><h3>Dê a volta completa</h3><p>Cante até o objeto voltar ao dono. Pergunte: o que se repetiu?</p></li><li><h3>Crie uma condição nova</h3><p>Sempre que a palavra "Zigue-Zigue-Zá" for cantada, o objeto fica retido na mão por dois tempos antes de voltar ao fluxo.</p></li><li><h3>Nomeie o conceito</h3><p>Explique que o laço de repetição mudou por causa de uma condição. Peça que a turma proponha outra regra.</p></li></ol>',
                                                                                                                                                                                             'Se a turma estiver agitada, faça a primeira rodada sem a regra do "Zigue-Zigue-Zá" e só depois a introduza.',
                                                                                                                                                                                             '<ul><li><strong>Copo, pedra ou tampinha</strong><span>Um objeto por criança.</span></li><li><strong>Espaço para a roda</strong><span>Sala ou pátio, com a turma sentada.</span></li><li><strong>A cantiga</strong><span>Cantada pela própria turma.</span></li></ul>',
                                                                                                                                                                                             'Repetição (loop) é executar o mesmo conjunto de comandos várias vezes. Uma condição pode alterar o que acontece em cada volta.'),

                                                                                                                                                                                            ('robo-humano', 'O Robô Humano', 'Uma criança vira robô e outra programadora: comandos verbais precisos para chegar ao destino sem errar.', 'f', 'Folclore', 'Algoritmos', 20, '4 a 10 anos', 'Sala ou pátio',
                                                                                                                                                                                             'Compreender que um algoritmo é uma sequência de passos precisos e sem ambiguidade. O aluno percebe que o "robô" executa exatamente o que foi programado — nem mais, nem menos.',
                                                                                                                                                                                             '<ol class="passos"><li><h3>Divida em duplas</h3><p>Uma criança é o "Programador" e a outra é o "Robô". O Robô fecha os olhos ou é vendado.</p></li><li><h3>Defina o objeto-alvo</h3><p>Coloque um brinquedo, cone ou mochila no lado oposto da sala. O Programador deve guiar o Robô até lá.</p></li><li><h3>Use apenas comandos simples</h3><p>Somente: "um passo à frente", "gire 90° para a esquerda", "gire 90° para a direita", "pare". O Robô executa exatamente o que ouve.</p></li><li><h3>Troque os papéis</h3><p>Após 2 minutos, troque. Na roda, pergunte: o que foi difícil?</p></li><li><h3>Versão avançada (6-10 anos)</h3><p>O Programador escreve TODOS os comandos antes de o Robô começar.</p></li></ol>',
                                                                                                                                                                                             'Se o Robô bater em um obstáculo, chame isso de "bug" e proponha depurar a instrução que causou o erro.',
                                                                                                                                                                                             '<ul><li><strong>Espaço aberto</strong><span>Sala ou pátio com espaço para caminhar.</span></li><li><strong>Objeto-alvo</strong><span>Brinquedo, cone ou mochila como destino.</span></li><li><strong>Venda (opcional)</strong><span>Para a versão imersiva com os olhos fechados.</span></li><li><strong>Papel e lápis</strong><span>Para a versão avançada com registro escrito.</span></li></ul>',
                                                                                                                                                                                             'Algoritmo é uma sequência finita e precisa de instruções para resolver um problema. Cada passo importa e a ordem não pode ser trocada.'),

                                                                                                                                                                                            ('sequencia-do-dia', 'A Sequência do Dia', 'Ordenar as ações da rotina matinal revela que algoritmos do cotidiano têm uma ordem que não pode ser trocada.', 'p', 'Língua Portuguesa', 'Sequenciamento', 25, '6 a 10 anos', 'Sala de aula',
                                                                                                                                                                                             'Compreender que a ordem das ações em um algoritmo é essencial. Ao reorganizar passos conhecidos de uma rotina diária, as crianças percebem que um código fora de ordem gera resultados absurdos.',
                                                                                                                                                                                             '<ol class="passos"><li><h3>Escreva ou desenhe a rotina</h3><p>Peça que cada aluno registre o passo a passo de escovar os dentes.</p></li><li><h3>Compare os algoritmos</h3><p>Coloque as sequências no quadro. Todos fizeram na mesma ordem?</p></li><li><h3>Proponha a ordem errada</h3><p>Pergunte: "E se colocarmos a pasta na boca ANTES de pegar a escova?"</p></li><li><h3>Crie cartões embaralhados</h3><p>Distribua cartões com as ações ilustradas fora de ordem para reordenar.</p></li><li><h3>Reflexão</h3><p>Peça que a turma cite outra rotina do dia que também seja um algoritmo.</p></li></ol>',
                                                                                                                                                                                             'Se os alunos discordarem da ordem entre si, use isso para mostrar que algoritmos precisam ser precisos.',
                                                                                                                                                                                             '<ul><li><strong>Papel e lápis</strong><span>Para cada aluno registrar sua sequência.</span></li><li><strong>Cartões ilustrados</strong><span>Com as ações da rotina para embaralhar.</span></li><li><strong>Quadro branco</strong><span>Para comparar as sequências da turma.</span></li></ul>',
                                                                                                                                                                                             'Sequenciamento é organizar instruções em uma ordem lógica e precisa. Trocar a posição de um passo pode inutilizar o algoritmo inteiro.'),

                                                                                                                                                                                            ('caca-ao-caminho', 'Caça ao Caminho', 'Com fita no chão e instruções escritas, a turma descobre que um robô precisa de direções absolutas, não de intenções.', 'm', 'Matemática', 'Algoritmos e Direções', 25, '6 a 10 anos', 'Sala ou pátio',
                                                                                                                                                                                             'Criar instruções de navegação claras e precisas em um grid físico. As crianças percebem que um algoritmo precisa de quantidades e direções exatas para funcionar.',
                                                                                                                                                                                             '<ol class="passos"><li><h3>Monte o grid</h3><p>Use fita crepe para criar uma grade de 5×5 no chão. Marque um ponto de partida e um tesouro.</p></li><li><h3>Escreva as instruções</h3><p>Em grupos, os alunos escrevem um algoritmo para ir do ponto A ao tesouro.</p></li><li><h3>Execute o algoritmo</h3><p>Um colega faz o papel do robô e segue as instruções escritas exatamente.</p></li><li><h3>Depure os erros</h3><p>Se o robô não chegar ao tesouro, o grupo identifica qual passo estava errado e corrige.</p></li><li><h3>Desafio extra</h3><p>Adicione obstáculos no caminho para desviar.</p></li></ol>',
                                                                                                                                                                                             'Incentive os grupos a contarem os passos primeiro desenhando o caminho no papel.',
                                                                                                                                                                                             '<ul><li><strong>Fita crepe</strong><span>Para criar o grid no chão.</span></li><li><strong>Objeto-tesouro</strong><span>Um brinquedo ou cone como destino.</span></li><li><strong>Papel e lápis</strong><span>Para escrever o algoritmo de navegação.</span></li><li><strong>Blocos de obstáculo</strong><span>Caixas ou garrafas para o desafio extra.</span></li></ul>',
                                                                                                                                                                                             'Algoritmos de navegação precisam de direções e quantidades exatas. Um computador não interpreta intenções — executa comandos literais.'),

                                                                                                                                                                                            ('classificando-objetos', 'Classificando Objetos', 'Agrupar sucatas por cor, forma e material ensina que todo banco de dados tem uma lógica de categorias.', 'm', 'Matemática', 'Reconhecimento de padrões', 20, '4 a 8 anos', 'Sala de aula',
                                                                                                                                                                                             'Identificar semelhanças e diferenças entre objetos para criar categorias. As crianças percebem que classificar é encontrar padrões para organizar informações.',
                                                                                                                                                                                             '<ol class="passos"><li><h3>Espalhe os objetos</h3><p>Coloque tampinhas, botões e sucatas sobre a mesa.</p></li><li><h3>Primeira rodada — por material</h3><p>Agrupe os objetos pelo material de que são feitos.</p></li><li><h3>Segunda rodada — por cor</h3><p>Desfaça os grupos e recomece usando o critério de cor.</p></li><li><h3>Terceira rodada — por tamanho</h3><p>Separe em pequeno, médio e grande.</p></li><li><h3>Invenção da regra</h3><p>Cada criança inventa sua própria regra de classificação.</p></li></ol>',
                                                                                                                                                                                             'Pergunte: "Se você fosse um computador guardando esses objetos, qual regra escolheria para achar mais rápido depois?"',
                                                                                                                                                                                             '<ul><li><strong>Tampinhas e botões</strong><span>Sucata variada para classificar.</span></li><li><strong>Rolos de papel e EVA</strong><span>Objetos de formas e materiais diferentes.</span></li><li><strong>Caixas ou círculos de cartolina</strong><span>Para separar visualmente os grupos.</span></li></ul>',
                                                                                                                                                                                             'Reconhecimento de padrões é identificar semelhanças e diferenças para criar categorias. É a base da organização de dados.'),

                                                                                                                                                                                            ('montando-historias', 'Montando Histórias', 'Cartões embaralhados de uma história: a turma descobre que o texto tem um algoritmo — começo, meio e fim.', 'p', 'Língua Portuguesa', 'Decomposição', 30, '6 a 10 anos', 'Sala de aula',
                                                                                                                                                                                             'Decompor uma história em partes menores e identificar a lógica que une cada trecho. As crianças percebem que uma narrativa fora de ordem perde o sentido.',
                                                                                                                                                                                             '<ol class="passos"><li><h3>Escolha a história</h3><p>Divida um conto curto em 5 a 7 cenas principais em cartões separados.</p></li><li><h3>Embaralhe e distribua</h3><p>Cada grupo recebe os cartões fora de ordem.</p></li><li><h3>Ordene as cenas</h3><p>O grupo discute e coloca os cartões na sequência correta.</p></li><li><h3>Apresente e compare</h3><p>Cada grupo apresenta sua ordenação para a turma.</p></li><li><h3>Crie a própria história</h3><p>A turma cria uma história nova em cartões para outro grupo ordenar.</p></li></ol>',
                                                                                                                                                                                             'Conecte com o conceito de decomposição: a história grande foi dividida em partes menores para ser mais fácil de entender.',
                                                                                                                                                                                             '<ul><li><strong>Cartões de cenas</strong><span>Um trecho ou ilustração por cartão.</span></li><li><strong>Conto impresso ou lido</strong><span>Uma história que a turma já conheça.</span></li><li><strong>Canetinhas e papel</strong><span>Para criar a história nova na etapa final.</span></li></ul>',
                                                                                                                                                                                             'Decomposição é dividir um problema grande em partes menores para facilitar a análise e a solução.'),

                                                                                                                                                                                            ('desafio-labirinto', 'Desafio do Labirinto', 'Labirinto no chão com bifurcações: siga o caminho verde se a condição for verdadeira, o vermelho se for falsa.', 'm', 'Matemática', 'Condicionais', 25, '6 a 10 anos', 'Pátio ou sala grande',
                                                                                                                                                                                             'Compreender o conceito de condicional: bifurcações onde a escolha do caminho depende de uma condição ser verdadeira ou falsa.',
                                                                                                                                                                                             '<ol class="passos"><li><h3>Construa o labirinto</h3><p>Com fita crepe, crie um caminho com 2 ou 3 bifurcações e cartões de pergunta.</p></li><li><h3>Marque os caminhos</h3><p>Fita verde = caminho do SIM. Fita vermelha = caminho do NÃO.</p></li><li><h3>Percorra o labirinto</h3><p>Cada criança entra e escolhe o caminho com base na sua resposta para a condição.</p></li><li><h3>Troca de condições</h3><p>A turma propõe novas condições para mudar os caminhos.</p></li><li><h3>Reflexão</h3><p>Desenhe o labirinto no quadro como um fluxograma.</p></li></ol>',
                                                                                                                                                                                             'Use condições divertidas e pessoais: "Tem irmão?" ou "Gosta de cachorro?"',
                                                                                                                                                                                             '<ul><li><strong>Fita crepe verde e vermelha</strong><span>Para os caminhos de SIM e NÃO.</span></li><li><strong>Cartões de condição</strong><span>Um por bifurcação com a pergunta escrita.</span></li><li><strong>Espaço amplo</strong><span>Pátio ou sala com mesas afastadas.</span></li></ul>',
                                                                                                                                                                                             'Condicional (Se/Senão) é uma bifurcação no algoritmo: dependendo se uma condição é verdadeira ou falsa, o programa segue um caminho diferente.'),

                                                                                                                                                                                            ('receita-algoritmo', 'A Receita Algorítmica', 'Escrever a receita do bolo da vovó passo a passo revela que qualquer tarefa pode ser descrita como algoritmo.', 'p', 'Língua Portuguesa', 'Algoritmos', 20, '6 a 10 anos', 'Sala de aula',
                                                                                                                                                                                             'Perceber que qualquer receita culinária é um algoritmo. A turma pratica escrita sequencial precisa e descobre o que acontece com passos ambíguos.',
                                                                                                                                                                                             '<ol class="passos"><li><h3>Apresente a analogia</h3><p>Mostre uma receita simples e identifique os ingredientes (variáveis) e passos (comandos).</p></li><li><h3>Escreva uma receita em grupo</h3><p>Cada grupo escreve a receita com máxima precisão de quantidades e ordem.</p></li><li><h3>Teste a receita de outro grupo</h3><p>Um integrante lê em voz alta enquanto outro executa ao pé da letra.</p></li><li><h3>Encontre os bugs</h3><p>Identifique os passos vagos que geraram erros e reescreva.</p></li><li><h3>Compare com um algoritmo real</h3><p>Mostre no quadro o pseudocódigo de uma tarefa e compare.</p></li></ol>',
                                                                                                                                                                                             'Se alguém escrever "açúcar a gosto", questione quanto é "a gosto" para introduzir a precisão de parâmetros.',
                                                                                                                                                                                             '<ul><li><strong>Papel e lápis</strong><span>Para escrever as receitas algorítmicas.</span></li><li><strong>Exemplo de receita</strong><span>Uma receita impressa para análise inicial.</span></li><li><strong>Quadro branco</strong><span>Para comparar receita e pseudocódigo.</span></li></ul>',
                                                                                                                                                                                             'Algoritmo é uma sequência precisa e sem ambiguidade de passos. Uma receita bem escrita é um algoritmo para cozinhar.'),

                                                                                                                                                                                            ('padroes-da-natureza', 'Padrões da Natureza', 'Folhas, flores e simetrias: identificar padrões visuais no mundo natural é o primeiro passo para programar.', 'm', 'Matemática', 'Reconhecimento de padrões', 20, '4 a 8 anos', 'Sala ou jardim',
                                                                                                                                                                                             'Desenvolver o olhar para padrões em contextos naturais e reconhecer que a natureza repete formas e estruturas.',
                                                                                                                                                                                             '<ol class="passos"><li><h3>Coletar amostras</h3><p>Colete folhas, flores e pedrinhas no jardim.</p></li><li><h3>Observe e descreva</h3><p>Em duplas, descrevam os padrões visíveis e regularidades.</p></li><li><h3>Reproduza o padrão</h3><p>Copie o padrão no papel e escreva a regra básica em palavras.</p></li><li><h3>Crie um padrão novo</h3><p>Monte um padrão com tampinhas coloridas usando uma regra definida.</p></li><li><h3>Conecte com programação</h3><p>Mostre que criar um padrão com regra é equivalente a um laço (loop).</p></li></ol>',
                                                                                                                                                                                             'A espiral de uma concha ou os hexágonos da colmeia são ótimos exemplos de padrões com regras matemáticas.',
                                                                                                                                                                                             '<ul><li><strong>Folhas e flores naturais</strong><span>Coletadas do jardim ou imagens impressas.</span></li><li><strong>Papel e canetinhas</strong><span>Para reproduzir e criar padrões.</span></li><li><strong>Tampinhas coloridas</strong><span>Para montar padrões com regras inventadas.</span></li></ul>',
                                                                                                                                                                                             'Reconhecimento de padrões é identificar regularidades e repetições. Um padrão com regra é a base para o uso de loops.'),

                                                                                                                                                                                            ('ciranda-algoritmica', 'Ciranda Algorítmica', 'A brincadeira de roda vira um programa com loops aninhados e condições que mudam a coreografia.', 'f', 'Folclore', 'Loop aninhado', 25, '6 a 10 anos', 'Pátio ou sala',
                                                                                                                                                                                             'Vivenciar corporalmente o conceito de loop aninhado — um loop dentro de outro — usando uma cantiga de roda.',
                                                                                                                                                                                             '<ol class="passos"><li><h3>Monte a ciranda</h3><p>Cante "Ciranda, Cirandinha" girando para a direita (loop externo).</p></li><li><h3>Insira o loop interno</h3><p>A cada trecho da música, a turma executa um gesto que se repete 3 vezes.</p></li><li><h3>Adicione a condição</h3><p>Ao sinal de palmas do professor, inverte-se o sentido da roda.</p></li><li><h3>Crie variações</h3><p>A turma propõe novas condições e gestos.</p></li><li><h3>Reflita</h3><p>Conte quantas voltas e gestos totais foram realizados.</p></li></ol>',
                                                                                                                                                                                             'Nomeie os loops em voz alta durante a brincadeira: "esse gesto que se repete é o nosso loop interno!"',
                                                                                                                                                                                             '<ul><li><strong>Espaço para a roda</strong><span>Pátio ou sala com mesas afastadas.</span></li><li><strong>A canção</strong><span>Ciranda Cirandinha, cantada pela turma.</span></li><li><strong>Cartões de condição</strong><span>Opcional, com os gestos escritos.</span></li></ul>',
                                                                                                                                                                                             'Loop aninhado é um laço de repetição dentro de outro. O loop externo controla a volta da roda; o interno controla os gestos dentro de cada volta.'),

                                                                                                                                                                                            ('historia-decomposta', 'A História Decomposta', 'Decomponha um conto em personagens, cenários e eventos para ver como o computador divide para conquistar.', 'p', 'Língua Portuguesa', 'Decomposição', 30, '6 a 10 anos', 'Sala de aula',
                                                                                                                                                                                             'Aplicar o pilar da decomposição ao analisar uma história conhecida, separando-a em categorias menores.',
                                                                                                                                                                                             '<ol class="passos"><li><h3>Escolha e conte o conto</h3><p>Relembre um conto popular com a turma.</p></li><li><h3>Crie as colunas de decomposição</h3><p>No quadro, faça 3 colunas: PERSONAGENS, CENÁRIOS, EVENTOS.</p></li><li><h3>Decomponha individualmente</h3><p>Em grupos, preencha o papel dividido nas 3 colunas.</p></li><li><h3>Compare as decomposições</h3><p>Os grupos apresentam e discutem o que é um detalhe essencial.</p></li><li><h3>Monte a história com peças separadas</h3><p>Crie uma história nova combinando os elementos decompostos.</p></li></ol>',
                                                                                                                                                                                             'Conecte com programação: em um jogo de videogame, personagens, cenários e eventos são objetos separados.',
                                                                                                                                                                                             '<ul><li><strong>Conto impresso ou narrado</strong><span>Um conto popular que a turma já conheça.</span></li><li><strong>Papel dividido em 3 colunas</strong><span>Personagens, Cenários, Eventos.</span></li><li><strong>Canetinhas</strong><span>Para desenhar ou escrever nas colunas.</span></li></ul>',
                                                                                                                                                                                             'Decomposição é dividir um problema complexo em partes menores e independentes para facilitar a solução.');